INSERT INTO "waivers_waiver_types" ("id", "name", "description", "document_id", "template_path", "retention_policy", "convert_to_pdf", "is_active", "modified", "created", "created_by", "modified_by", "deleted", "exemption_reasons") VALUES
(1, 'Participation Roster Waiver', 'Consent to Participate and Release Liability - required for all non-members.', NULL, 'https://www.sca.org/wp-content/uploads/2019/12/rosterwaiver.pdf', '{"anchor":"gathering_end_date","duration":{"years":7}}', TRUE, TRUE, '2025-11-06 21:10:06', '2025-10-30 21:12:58', 1, 1, NULL, '["Activity was Cancelled","All Participants had Blue Cards"]'),
(2, 'Equestrian Activity Waiver', 'When horses are at the event.', NULL, 'https://www.sca.org/wp-content/uploads/2024/03/AdultEquestrianWaivers2024.pdf', '{"anchor":"gathering_end_date","duration":{"years":7}}', TRUE, TRUE, '2025-11-02 01:43:23', '2025-11-02 01:43:23', 1, 1, NULL, NULL),
(3, 'Minor Waivers', 'Minor Waivers are required to be signed by the parent or legal guardian for any minor (a person under the age of majority, usually 18) who is attending an SCA event or participating in a covered activity.', NULL, 'https://www.sca.org/wp-content/uploads/2024/04/chldwaiv.pdf', '{"anchor":"gathering_end_date","duration":{"years":20}}', TRUE, TRUE, '2025-11-18 02:34:43', '2025-11-02 02:12:15', 1, 1, NULL, '["No Minor present."]'),
(4, 'Family Minor Waiver', 'For families with more than one child, Family Minor Waivers are required to be signed by the parent or legal guardian for any minors (persons under the age of majority, usually 18) who is attending an SCA event or participating in a covered activity.', NULL, 'https://sca.org/wp-content/uploads/2024/09/waiver_minor_family.pdf', '{"anchor":"gathering_end_date","duration":{"years":20}}', TRUE, TRUE, '2025-11-02 02:13:41', '2025-11-02 02:12:52', 1, 1, NULL, NULL),
(5, 'Gate Sign-In Sheets', 'The papers from Gate where all attendees signed into the event and documentation of their membership status was reviewed in person.', NULL, 'https://ansteorra.org/exchequer/event-reports/', '{"anchor":"gathering_end_date","duration":{"years":7}}', TRUE, TRUE, '2025-11-06 01:32:09', '2025-11-06 01:32:09', 1, 1, NULL, NULL),
(6, 'All Blue Cards', 'Choose this option when all martial participants have shown their blue membership card.', NULL, NULL, '{"anchor":"gathering_end_date","duration":{"years":7}}', TRUE, FALSE, '2025-11-11 03:24:31', '2025-11-06 02:15:53', 1, 1, NULL, '["Activity was cancelled."]')
